#!/usr/bin/env python3
"""Regenerate ground truth for CSX-186_Q2."""

from __future__ import annotations

import csv
import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-186_Q2"
EVENT_ID = "CSX-186"
PACKAGE_ID = "CSX-186"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_001_Locked_anchor_report_NASA_Earth_Observatory.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_2020_Cameron_Peak_and_East_Troublesome_fires.json",
]

THRESHOLDS = {
    "explosive_growth_acres_per_hour_gt": 5000,
    "residual_control_gap_percent_ge": 80,
    "snow_moderation_inches_ge": 6,
}


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    def text(self) -> str:
        return " ".join(self.parts)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8-sig"))


def read_html_text(package: Path, rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package / rel_path).read_text(encoding="utf-8", errors="replace"))
    return parser.text()


def require_manifest_paths(package: Path, rel_paths: list[str]) -> None:
    with (package / "metadata/files.csv").open(newline="", encoding="utf-8-sig") as handle:
        manifest_paths = {row["relative_path"] for row in csv.DictReader(handle)}
    for rel_path in rel_paths:
        if rel_path.startswith("metadata/"):
            continue
        if rel_path not in manifest_paths:
            raise ValueError(f"Source file is not listed in metadata/files.csv: {rel_path}")


def first_int(pattern: str, text: str, flags: int = 0) -> int:
    match = re.search(pattern, text, flags)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1).replace(",", ""))


def first_float_pair(pattern: str, text: str, flags: int = 0) -> tuple[float, float]:
    match = re.search(pattern, text, flags)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1)), float(match.group(2))


def compact_json_size(value: Any) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def main() -> None:
    package = package_dir()
    require_manifest_paths(package, SOURCE_FILES)

    event = read_json(package, "metadata/event.json")
    if event.get("package_id") != PACKAGE_ID:
        raise ValueError("Unexpected package_id in metadata/event.json")
    if event.get("hazard_family") != "wildfire_burn_smoke":
        raise ValueError("Unexpected hazard_family in metadata/event.json")

    anchor = read_json(
        package,
        "data/event_reports/event_reports_003_Locked_event_anchor_2020_Cameron_Peak_and_East_Troublesome_fires.json",
    )
    report_text = read_html_text(
        package,
        "data/event_reports/event_reports_001_Locked_anchor_report_NASA_Earth_Observatory.html",
    )

    growth_start = first_int(r"growing from ([\d,]+) acres to [\d,]+ acres in about 24 hours", report_text)
    growth_end = first_int(r"growing from [\d,]+ acres to ([\d,]+) acres in about 24 hours", report_text)
    containment_percent = first_int(r"it was ([\d,]+) percent contained", report_text)
    snow_min, snow_max = first_float_pair(r"received about ([\d.]+) to ([\d.]+) inches", report_text)

    growth_hours = 24
    growth_increase = growth_end - growth_start
    growth_rate = growth_increase / growth_hours
    not_contained_percent = 100 - containment_percent
    snow_midpoint = (snow_min + snow_max) / 2.0

    threshold_flags = {
        "explosive_growth": "pass"
        if growth_rate > THRESHOLDS["explosive_growth_acres_per_hour_gt"]
        else "fail",
        "residual_control_gap": "pass"
        if not_contained_percent >= THRESHOLDS["residual_control_gap_percent_ge"]
        else "fail",
        "snow_moderation": "pass"
        if snow_midpoint >= THRESHOLDS["snow_moderation_inches_ge"]
        else "fail",
    }
    ledger_pass_count = sum(1 for value in threshold_flags.values() if value == "pass")
    final_state = (
        "temporary_snow_slowdown_residual_risk"
        if threshold_flags["residual_control_gap"] == "pass"
        else "snow_ends_incident"
    )

    expected_values = {
        "growth_increase_acres": growth_increase,
        "growth_rate_acres_per_hour": round(growth_rate, 1),
        "not_contained_percent": not_contained_percent,
        "snow_midpoint_inches": round(snow_midpoint, 1),
        "ledger_pass_count": ledger_pass_count,
    }
    tolerances = {
        "growth_increase_acres": 1000,
        "growth_rate_acres_per_hour": 50,
        "not_contained_percent": 1,
        "snow_midpoint_inches": 0.5,
    }

    primary_gt = {
        "target_family": "threshold_ledger",
        "answer": final_state,
        "required_fields": [
            "growth_increase_acres",
            "growth_rate_acres_per_hour",
            "not_contained_percent",
            "snow_midpoint_inches",
            "threshold_flags",
            "ledger_pass_count",
            "final_state",
            "one_sentence_interpretation",
        ],
        "expected_values": expected_values,
        "thresholds": THRESHOLDS,
        "threshold_flags": threshold_flags,
        "tolerances": tolerances,
        "decision_rule": "Classify as temporary_snow_slowdown_residual_risk when residual_control_gap passes; snow_ends_incident requires residual_control_gap to fail.",
    }

    if len(primary_gt) > 8 or compact_json_size(primary_gt) >= 1200:
        raise ValueError("primary_gt must stay compact")

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "threshold_ledger",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": "2020 East Troublesome fire",
            "hazard_family": event["hazard_family"],
            "event_window": anchor["temporal_window"],
            "location": anchor["spatial_window"]["location_text"],
            "formulae": {
                "growth_increase_acres": "growth_end_acres - growth_start_acres",
                "growth_rate_acres_per_hour": "growth_increase_acres / 24",
                "not_contained_percent": "100 - containment_percent",
                "snow_midpoint_inches": "(snow_min_inches + snow_max_inches) / 2",
            },
            "source_values": {
                "growth_start_acres": growth_start,
                "growth_end_acres": growth_end,
                "growth_hours": growth_hours,
                "containment_percent": containment_percent,
                "snow_range_inches": [snow_min, snow_max],
            },
            "expected_values": expected_values,
            "threshold_flags": threshold_flags,
            "final_state": final_state,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "final state and schema",
                    "points": 4,
                    "description": "Returns the requested compact JSON ledger and the final_state temporary_snow_slowdown_residual_risk.",
                    "partial_credit": "Award 2-3 points for the correct state with missing fields; award 0-1 for snow_ends_incident or a choice-list answer.",
                },
                {
                    "name": "metric extraction and formulas",
                    "points": 4,
                    "description": "Correctly computes the 140,000-acre increase, 5,833.3-acre-per-hour growth rate, 85 percent not contained, and 9.0-inch snow midpoint.",
                    "partial_credit": "Award about 1 point per correct metric within tolerance; withhold credit for values copied without the required derived operation.",
                },
                {
                    "name": "threshold flags",
                    "points": 4,
                    "description": "Applies the three inequalities correctly: growth rate > 5,000, not-contained share >= 80, and snow midpoint >= 6, yielding three pass flags.",
                    "partial_credit": "Award 2-3 points for one wrong flag or minor inequality confusion; award 1 point for recognizing only the snow threshold.",
                },
                {
                    "name": "decision-rule proof",
                    "points": 4,
                    "description": "Shows that the residual-control-gap pass blocks an incident-ending classification even though the snow-moderation test passes.",
                    "partial_credit": "Award 2-3 points for the right conclusion without explicit rule logic; award 0-1 for treating snow magnitude alone as decisive.",
                },
                {
                    "name": "rejected state",
                    "points": 3,
                    "description": "Rejects snow_ends_incident or perimeter-only reasoning using the computed growth and containment thresholds.",
                    "partial_credit": "Award 1-2 points for rejecting the weaker state without citing both threshold anchors.",
                },
                {
                    "name": "precision and restraint",
                    "points": 1,
                    "description": "Uses units, reasonable rounding, and a one-sentence interpretation that stays within the computed threshold result.",
                    "partial_credit": "Award partial credit for a readable answer with minor rounding or wording issues.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    (task_dir() / "computed_gt.json").write_text(
        json.dumps(computed_gt, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
